  more:'M5 12h.01M12 12h.01M19 12h.01',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7v5l3 2',up:'m6 14 6-6 6 6',down:'m6 10 6 6 6-6',
